import {normalized} from './helper.js';
export default async function main({actions,readText},input) {
 const tree = await actions.DOM.getAXTree({purpose:'读取测试页面'});
 const text = await readText(tree.artifact);
 await actions.Input.type({selector:'#name',text:normalized(input.name),clear:true,delayMs:0,purpose:'填入本轮测试变量'});
 const facts=await actions.DOM.getDetails({query:{view:'state',targets:[{selector:'#name'}]},purpose:'校验测试字段'});
 return {name:input.name,values:input.values.map(x=>x*2),treeChars:text.length,details:facts.details};
}

